/* Personal action workspace; the existing archive remains the canonical visual index. */
(() => {
  'use strict';
  const M=window.PersonalAssetsModel,$=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const button=(a,label,cls='',value='')=>`<button type="button" class="pa-btn ${cls}" data-pa="${a}" data-id="${esc(value)}" ${a==='close-agent'?'aria-label="收起 Ask Agent"':a==='modal-cancel'&&label==='×'?'aria-label="关闭对话框"':''}>${label}</button>`;
  const personal=()=>document.body.dataset.wsType!=='team';
  const seeds=todayAssetRecords.filter(r=>['todo','schedule'].includes(r.type)).map(r=>({...r,start:(r.eventDate||r.dueDate)+'T'+r.time,end:r.end?(r.eventDate+'T'+r.end):'',source:'capture',notes:'',reminder:r.type==='schedule'?'15':'none',location:r.type==='schedule'?(r.id==='schedule-1'?'线上会议':'会议室 A'):'',participants:r.type==='schedule'?(r.id==='schedule-1'?'Kevin、张伟':'Alice、张伟'):'',links:[],capture:r.detail,created:(r.createdDate||r.eventDate||r.dueDate)+'T09:19:00+08:00',updated:'seed'}));
  for(const file of thoughtArchiveData.todo.files)for(const [i,r] of file.entries.entries())if(!r.assetId){const id=`archive-todo-${file.month}-${i}`;seeds.push({...r,id,type:'todo',start:r.date+'T'+r.time,end:'',source:'capture',reminder:'none',notes:'',location:'',participants:'',links:[],done:r.detail.includes('已完成'),capture:r.detail,created:r.date+'T'+r.time+':00+08:00',updated:'seed'});}
  const firstMeeting=window.MeetingDetail?.snapshot()?.[0];if(firstMeeting)seeds.filter(r=>r.type==='schedule').forEach(r=>r.links=[firstMeeting.id]);
  let repo;try{repo=M.create(localStorage,seeds);}catch(e){showToast(e.message);return;}
  let selected=null,editing=false,draft=null,draftBaseline='',listType='todo',agentDraft=null,sessionId=null,recordingAsset=null;
  const root=document.createElement('section');root.id='personal-actions';root.className='main-inner pa-workspace';root.dataset.mainView='personal-actions';root.hidden=true;root.innerHTML='<div class="pa-content"></div>';$('.main').append(root);const content=$('.pa-content',root);
  const nav=document.createElement('button');nav.type='button';nav.id='todos-entry';nav.className='nav-item';nav.dataset.pa='todos';nav.innerHTML='<span class="nav-left"><span class="nav-icon"><svg class="icon" viewBox="0 0 24 24"><path d="m3 5 2 2 3-4M11 5h10M3 12l2 2 3-4M11 12h10M3 19l2 2 3-4M11 19h10"/></svg></span><span class="nav-label">To-dos</span></span>';
  const contact=$('[data-contacts-entry]');(contact.closest('.knowledge-tree-leaf-row')||contact).before(nav);
  $('#thought-toolbar').insertAdjacentHTML('beforeend',button('new-schedule','＋ 新建日程','primary')+button('agent','✧ Ask Agent'));
  const archiveWrap=document.createElement('div');archiveWrap.className='pa-archive-wrap';$('#recording-card').before(archiveWrap);archiveWrap.append($('#recording-card'));
  const rail=document.createElement('aside');rail.id='pa-agent';rail.className='pa-agent';rail.hidden=true;rail.setAttribute('aria-label','闪念 Ask Agent');
  const dialog=document.createElement('dialog');dialog.className='pa-dialog';dialog.setAttribute('aria-label','编辑个人记录');document.body.append(dialog);let dialogAction=null,dialogCancel=null,dialogReturn=null;
  const source=r=>M.sources[r.source]||'闪念提取';
  const record=id=>repo.snapshot().records.find(r=>r.id===id);
  const meetings=()=>window.MeetingDetail.snapshot();
  const date=v=>{const value=String(v||'');if(/(?:Z|[+-]\d{2}:\d{2})$/.test(value)&&Number.isFinite(Date.parse(value)))return new Date(Date.parse(value)+8*3600000).toISOString().replace('T',' ').slice(0,16);return value.replace('T',' ').slice(0,16);};
  const field=(label,name,value='',type='text',extra='')=>`<label class="pa-field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
  const reminderSelect=r=>`<label class="pa-field">提醒时间<select name="reminder">${M.reminders.map(([v,t])=>`<option value="${v}" ${v===r.reminder?'selected':''}>${t}</option>`).join('')}</select></label>`;
  function formFields(r){return `${field('标题','title',r.title,'text','required maxlength="200" placeholder="为这次安排起个名字"')}<div class="pa-form-grid">${field(r.type==='schedule'?'开始时间':'截止时间','start',r.start,'datetime-local','required')}${r.type==='schedule'?field('结束时间','end',r.end,'datetime-local','required'):''}${reminderSelect(r)}<p class="pa-hint">时间统一按 GMT+8（北京时间）</p></div>${r.type==='schedule'?`<div class="pa-form-grid">${field('地点','location',r.location,'text','maxlength="300" placeholder="线上链接或会议地点"')}${field('参与人','participants',r.participants,'text','maxlength="300" placeholder="用顿号分隔姓名"')}</div>`:''}<label class="pa-field">我的备注<textarea name="notes" maxlength="2000" rows="4" placeholder="补充需要记住的内容">${esc(r.notes)}</textarea><small>最多 2000 字</small></label>`;}
  function values(form,base){return {...base,...Object.fromEntries(new FormData(form))};}
  function error(message,el=content){const box=$('[data-pa-error]',el);if(box){box.textContent=message;box.hidden=false;box.focus?.();}else showToast(message);}
  function modal(title,body,ok,onConfirm,onCancel){dialogReturn=document.activeElement;dialog.innerHTML=`<form method="dialog" class="pa-modal-form"><header><h2>${esc(title)}</h2>${button('modal-cancel','×','','')}</header>${body}<p role="alert" data-pa-error hidden></p><footer>${button('modal-cancel','取消')}${button('modal-confirm',ok,'primary')}</footer></form>`;dialogAction=onConfirm;dialogCancel=onCancel;dialog.showModal();}
  function closeModal(){dialog.close();dialogAction=null;dialogCancel=null;dialogReturn?.focus?.({preventScroll:true});}
  function confirmModal(){try{if(dialogAction?.()!==false)closeModal();}catch(e){error(e.message,dialog);}}
  dialog.addEventListener('cancel',e=>{e.preventDefault();cancelModal();});
  function cancelModal(){if(dialogCancel?.()===false)return;closeModal();}
  let continuation=null;
  function guard(fn){
    const form=$('#pa-edit-form');if(editing&&form)draft=values(form,draft);
    const assetDirty=editing&&JSON.stringify(draft)!==draftBaseline;
    const af=$('#pa-agent-form');if(agentDraft&&af)agentDraft=values(af,agentDraft);
    const agentDirty=!!agentDraft;
    if(!assetDirty&&!agentDirty)return false;
    if(continuation)return true;
    continuation=fn;
    modal('保留这次修改？','<p>还有未保存的内容。你可以继续编辑、放弃修改，或保存后继续。</p>'+button('discard','放弃修改'),'保存并继续',()=>{
      if(assetDirty&&!saveDraft(false))return false;
      if(agentDirty&&!confirmAgent(false))return false;
      editing=false;agentDraft=null;const next=continuation;continuation=null;queueMicrotask(next);
    },()=>{continuation=null;});
    return true;
  }
  function hideAgent(){if(!rail.hidden)rail.hidden=true;archiveWrap.classList.remove('pa-with-agent');root.classList.remove('pa-with-agent');}
  function view(title){showMainView('personal-actions',{silent:true});$('#page-crumb').textContent=title;$$('.nav-item,.side-sub-item').forEach(n=>{n.classList.remove('active');n.removeAttribute('aria-current');});if(listType==='todo'){nav.classList.add('active');nav.setAttribute('aria-current','page');}}
  function open(id){if(!personal())return;if(guard(()=>open(id)))return;const r=record(id);if(!r)return showToast('记录不存在');editing=false;selected=id;listType=r.type;view(r.type==='schedule'?'日程详情':'To-do 详情');hideAgent();renderDetail();}
  function showList(type='todo'){if(!personal())return;if(guard(()=>showList(type)))return;editing=false;selected=null;listType=type;view(type==='todo'?'To-dos':'日程');hideAgent();renderList();}
  let search='',status='pending';
  function renderList(){content.innerHTML=`<header class="pa-page-head"><div><p class="pa-eyebrow">个人工作空间</p><h1>${listType==='todo'?'To-dos':'日程'}</h1><p>从一次记录，到清晰的下一步。</p></div><div>${button('new-'+listType,listType==='todo'?'＋ 新建待办':'＋ 新建日程','primary')}${button('agent','✧ Ask Agent')}</div></header><section class="pa-card"><div class="pa-list-tools"><input id="pa-search" aria-label="搜索个人记录" placeholder="搜索标题、地点或参与人" value="${esc(search)}"><div>${listType==='todo'?['pending','done','all'].map((v,i)=>button('filter',['待完成','已完成','全部'][i],status===v?'selected':'',v)).join(''):button('archive','月度归档')}</div></div><div id="pa-list"></div></section>`;renderRows();}
  function renderRows(){const rows=repo.snapshot().records.filter(r=>r.type===listType&&(listType!=='todo'||status==='all'||r.done===(status==='done'))&&`${r.title} ${r.location} ${r.participants}`.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>a.start.localeCompare(b.start));$('#pa-list').innerHTML=rows.map(r=>`<button type="button" class="pa-list-row" data-personal-open="${esc(r.id)}"><span class="pa-list-symbol">${r.type==='todo'?(r.done?'✓':'○'):'▦'}</span><span><strong>${esc(r.title)}</strong><small>${date(r.start)}${r.type==='schedule'?' — '+date(r.end):r.done?' · 已完成':Date.parse(r.start+':00+08:00')<Date.now()?' · 已逾期':' · 待完成'} · GMT+8</small></span><span class="pa-source">${source(r)}</span><span>›</span></button>`).join('')||'<div class="pa-empty">暂无匹配的记录。试试其他筛选，或创建一条新记录。</div>';}
  function capture(r){if(r.source==='manual')return '<p class="pa-hint">此记录由你手动创建，没有原始录音。</p>';if(r.source==='agent')return `<p>由 Ask Agent 创建</p>${button('source-session','查看来源会话','',r.sessionId)}`;return `<details open><summary>原始捕获</summary><p>${esc(r.capture||r.detail||r.title)}</p><small>捕获于 ${date(r.created)} · 已处理</small><audio controls preload="metadata" src="assets/meeting-demo.wav" aria-label="原始捕获演示音频"></audio><small>演示音频 · 非真实原始录音</small></details>${button('recall','✧ 回顾当时的上下文')}`;}
  function renderDetail(){$$('audio',root).forEach(a=>a.pause());const r=record(selected);if(!r)return;content.innerHTML=`<header class="pa-page-head"><div>${button('back','← '+(r.type==='todo'?'To-dos':'日程列表'),'plain')}<h1>${esc(r.title)}</h1><span class="pa-source">${source(r)}</span>${r.type==='todo'?`<span class="pa-status ${r.done?'done':''}">${r.done?'已完成':'待完成'}</span>`:''}</div><div>${button('edit','编辑')}${button('agent','✧ Ask Agent')}</div></header><div class="pa-detail-grid"><div class="pa-detail-main"><section class="pa-card"><h2>${r.type==='todo'?'待办安排':'日程安排'}</h2><dl><div><dt>${r.type==='todo'?'截止时间':'日程时间'}</dt><dd>${date(r.start)}${r.type==='schedule'?' — '+date(r.end):''}<small>GMT+8 · 北京时间</small></dd></div>${r.type==='schedule'?`<div><dt>地点</dt><dd>${esc(r.location)||'未设置'}</dd></div><div><dt>参与人</dt><dd>${r.participants?r.participants.split(/[、,，]/).filter(Boolean).map(n=>`<span class="pa-person">${esc(n.trim())}</span>`).join(''):'未设置'}</dd></div>`:''}<div><dt>提醒时间</dt><dd>${button('edit-reminder',M.reminders.find(([v])=>v===r.reminder)?.[1]||'不提醒','plain')}</dd></div></dl><div class="pa-notice">${repo.snapshot().settings.notifications?'站内演示提醒已开启；页面关闭后不会推送。':'站内演示提醒未开启，当前不会提醒。'} ${button('notifications','设置','plain')}</div></section><section class="pa-card"><div class="pa-section-head"><h2>我的备注</h2>${button('notes',r.notes?'编辑备注':'添加备注')}</div><p class="pa-note">${esc(r.notes)||'记下需要确认的问题，或补充这次安排。'}</p></section>${r.type==='schedule'?`<section class="pa-card"><div class="pa-section-head"><h2>关联会议 <small>${r.links.length} 场</small></h2>${button('links','管理')}</div>${r.links.map(id=>{const m=meetings().find(x=>x.id===id);return m?button('meeting',`<strong>${esc(m.title)}</strong><small>${esc(m.created)} · ${esc(m.duration||'')} · ${esc(m.source)}</small>`,'pa-linked',id):'<p class="pa-hint">关联会议已删除或暂不可用</p>';}).join('')||'<p class="pa-hint">关联已有会议，方便回顾会议纪要。</p>'}</section>`:''}<footer class="pa-detail-footer">${r.type==='todo'?button('toggle',r.done?'重新打开待办':'标记完成','primary',r.id):button('record','♩ 开始录音','primary')}<small>${r.type==='schedule'?'会议开始了？录音完成后会自动关联到此日程。':'状态会同步到首页与全部闪念。'}</small></footer></div><aside class="pa-card pa-origin"><p class="pa-eyebrow">记录从哪里来</p><h2>${source(r)}</h2>${capture(r)}<p class="pa-hint">创建于 ${date(r.created)}<br>仅保存在当前个人工作空间</p></aside></div>`;}
  function newRecord(type){if(!personal())return;if(guard(()=>newRecord(type)))return;selected=null;listType=type;draft={id:M.id(),type,title:'',start:'',end:'',source:'manual',reminder:'none',notes:'',location:'',participants:'',links:[],done:false};showEditor();}
  function edit(){draft=record(selected);showEditor();}
  function showEditor(){editing=false;view(draft.type==='schedule'?'编辑日程':'编辑待办');editing=true;draftBaseline=JSON.stringify(draft);hideAgent();content.innerHTML=`<header class="pa-page-head"><div><p class="pa-eyebrow">${source(draft)} · GMT+8</p><h1>${selected?'编辑':'新建'}${draft.type==='schedule'?'日程':'待办'}</h1></div></header><form id="pa-edit-form" class="pa-card pa-editor">${formFields(draft)}<p role="alert" data-pa-error hidden></p><footer>${button('cancel-edit','退出编辑')}<button class="pa-btn primary" type="submit">保存</button></footer></form>`;$('#pa-edit-form [name=title]').focus();}
  function saveDraft(navigate=true){try{draft=values($('#pa-edit-form'),draft);const r=repo.save(draft);editing=false;selected=r.id;sync();if(navigate){view(r.type==='schedule'?'日程详情':'To-do 详情');renderDetail();}showToast('已保存');return true;}catch(e){error(e.message,dialog.open?dialog:content);return false;}}
  function toggle(id){try{const r=record(id);if(!r)return;repo.save({...r,done:!r.done});sync();if(!root.hidden){if(selected)renderDetail();else renderRows();}const checkbox=$(`[data-today-toggle="${id}"]`);checkbox?.focus({preventScroll:true});}catch(e){showToast(e.message);}}
  function sync(){
    const state=repo.snapshot();
    for(let i=todayAssetRecords.length-1;i>=0;i--)if(['todo','schedule'].includes(todayAssetRecords[i].type))todayAssetRecords.splice(i,1);
    for(const type of ['todo','schedule']){
      const records=state.records.filter(r=>r.type===type), groups={};
      for(const r of records){const day=r.start.slice(0,10),time=r.start.slice(11,16),detail=type==='schedule'?[r.location,r.participants,M.reminders.find(([v])=>v===r.reminder)?.[1],source(r)].filter(Boolean).join(' · '):`${r.done?'已完成':'待完成'} · ${r.capture||r.notes||''} · ${source(r)}`;
        todayAssetRecords.push({...r,eventDate:day,dueDate:day,time,end:r.end?.slice(11,16),detail});
        const month=day.slice(0,7);groups[month]||={month,count:0,updated:day+' '+time,entries:[]};groups[month].entries.push({date:day,time,title:r.title,detail,assetId:r.id});groups[month].count++;
      }
      thoughtArchiveData[type].files=Object.values(groups).sort((a,b)=>b.month.localeCompare(a.month));thoughtArchiveData[type].files.forEach(f=>f.entries.sort((a,b)=>(b.date+b.time).localeCompare(a.date+a.time)));
      const count=$(`[data-thought-category="${type}"] em`);if(count)count.textContent=records.length;
    }
    const monthSelect=$('#thought-month-select'),current=monthSelect.value;
    const months=[...new Set(Object.values(thoughtArchiveData).flatMap(c=>c.files.map(f=>f.month)))].sort().reverse();monthSelect.innerHTML='<option value="all">全部月份</option>'+months.map(m=>`<option value="${m}">${m.replace('-',' 年 ')} 月</option>`).join('');monthSelect.value=months.includes(current)?current:'all';
    renderTodayAssets();renderThoughtFiles();
    if(activeThoughtFile&&!$('#thought-preview').hidden){const file=thoughtArchiveData[activeThoughtCategory]?.files.find(f=>f.month===activeThoughtFile.month);if(file)renderThoughtPreview(file,$('#thought-preview-date-title').textContent);else $('#thought-preview').hidden=true;}
    restoreMeetings();
  }
  const restoredMeetings=new Set();
  function restoreMeetings(){for(const m of repo.snapshot().meetings){if($(`[data-meeting-id="${m.id}"]`)||restoredMeetings.has(m.id))continue;const row=$('#meeting-list .home-meeting-row')?.cloneNode(true);if(!row)continue;row.dataset.meetingId=m.id;row.dataset.meeting=m.title;row.dataset.view='my';row.dataset.recordingDate=date(m.created).slice(0,10);row.dataset.source='网页录音';row.dataset.meta=date(m.created)+' · 网页录音 · 演示';$('.home-meeting-title strong',row).textContent=m.title;$('.home-meeting-time',row).textContent=date(m.created);$('.home-meeting-updated',row).textContent=date(m.created);$('.home-meeting-size',row).textContent='演示音频';$('.home-meeting-tag',row).textContent='日程录音';const creator=$('.meeting-creator',row);if(creator){creator.textContent='张伟';creator.nextElementSibling.textContent='网页录音';}$('.home-meeting-tag',row).nextElementSibling.textContent=Math.max(1,Math.ceil(m.seconds/60))+' 分钟';row.addEventListener('click',e=>{if(!e.target.closest('[data-meeting-action]'))window.MeetingDetail.open(m.title);});$('#meeting-list').prepend(row);restoredMeetings.add(m.id);}filterMeetings();}
  function openArchive(){editing=false;hideAgent();showMainView('home',{silent:true});$('[data-meeting-view="thought"]').click();$('[data-thought-category="schedule"]').click();}
  function showAgent(id=null){if(!personal())return;if(!id&&!rail.hidden){$('#pa-prompt')?.focus({preventScroll:true});return;}if(agentDraft&&guard(()=>{agentDraft=null;showAgent(id);}))return;hideAgent();if(!root.hidden){root.append(rail);root.classList.add('pa-with-agent');}else{setXiaozhiExpanded(false);archiveWrap.append(rail);archiveWrap.classList.add('pa-with-agent');}rail.hidden=false;
    const session=id?repo.snapshot().sessions.find(s=>s.id===id):null;if(session){sessionId=session.id;agentDraft=null;renderAgent(session);}else{sessionId=null;agentDraft=null;renderAgent();}
  }
  function renderAgent(session=null){const r=selected?record(selected):null;rail.innerHTML=`<header><div><h2>✧ Ask Agent</h2><small>个人闪念 · 日程助手</small></div>${button('close-agent','×')}</header><div class="pa-agent-body"><p class="pa-hint">${session?'来源会话 · '+date(session.created):r?'已引用：'+esc(r.title):'在这里整理安排，或把想法变成日程。'}</p>${session?`<div class="pa-message">${esc(session.prompt)}</div>${session.recordId?`<p>日程已创建，可在日程列表中继续编辑。</p>${button('open-created','查看日程','',session.recordId)}`:'<p>这段对话尚未创建日程。补充信息后可以继续。</p>'}`:`<h3>下一次讨论，安排在什么时候？</h3><p>告诉我日期、时间和主题，我会先为你准备日程草稿。</p>${r?`<div class="pa-message">${esc(r.capture||r.notes||r.title)}</div>`:button('agent-example','试试：明天 14:00 讨论产品方案')}<p class="pa-hint">本地演示 · 支持明确日期或今天/明天/后天与时间；未连接外部 AI 服务。</p>`}<div id="pa-agent-result"></div></div><form id="pa-agent-prompt"><label class="sr-only" for="pa-prompt">给 Agent 的要求</label><textarea id="pa-prompt" rows="3" maxlength="2000" placeholder="例如：明天 14:00–15:00，安排「产品方案讨论」"></textarea><footer><small>确认后加入日程列表</small><button class="pa-btn primary" type="submit">发送</button></footer></form>`;$('#pa-prompt').focus({preventScroll:true});}
  function generate(prompt){if(!prompt.trim())return;try{const sid=M.id();repo.session({id:sid,prompt,created:new Date().toISOString()});sessionId=sid;agentDraft=M.parse(prompt);$('#pa-agent-result').innerHTML=`<div class="pa-message">${esc(prompt)}</div><h3>确认日程</h3><p>${agentDraft.start?'已填写时间，请核对后创建；未提供结束时间时，草稿暂按 30 分钟。':'还需要具体日期和时间，请在下方补充。'}</p><form id="pa-agent-form">${formFields(agentDraft)}<p role="alert" data-pa-error hidden></p><button class="pa-btn primary" type="submit">确认创建日程</button></form>`;$('#pa-agent-prompt').hidden=true;$('#pa-agent-result').scrollIntoView({block:'nearest'});}catch(e){showToast(e.message);}}
  function confirmAgent(render=true){try{agentDraft=values($('#pa-agent-form'),agentDraft);const r=repo.confirm(sessionId,agentDraft);agentDraft=null;sync();if(render){renderAgent(repo.snapshot().sessions.find(s=>s.id===sessionId));showToast('日程已加入列表');}return true;}catch(e){error(e.message,dialog.open?dialog:rail);return false;}}
  function setupSettings(){const page=$('#personal-settings');if(!page)return;const prefs=repo.snapshot().settings;const account=window.WorkspaceModel.load(localStorage);$('.settings-profile strong',page).textContent=account.account.email;$('.settings-profile small',page).textContent='Pro · 个人工作空间';
    $('.settings-float-toolbar-copy strong',page).textContent='Settings';$('.settings-float-toolbar-copy span',page).textContent='账户、语言与录音偏好';
    $('[data-settings-close]',page).setAttribute('aria-label','返回首页');
    const attrs=['language','summary-language','summary-detail','summary-template'];
    for(const attr of attrs)$$(`[data-settings-${attr}]`,page).forEach(el=>{const key=attr==='language'?el.dataset.settingsLanguage:attr;let val=prefs[key];if(val===undefined&&attr==='language')val=localStorage.getItem('eurekamind:settings:'+key);if(val!==undefined&&val!==null)el.value=val;el.addEventListener('change',event=>{event.stopImmediatePropagation();try{repo.settings({[key]:el.value});showToast('偏好已保存');}catch(e){showToast(e.message);}},{capture:true});});
    for(const [sel,key,def] of [['[data-settings-action="toggle-summary"]','autoSummary',true],['[data-settings-voiceprint]','voiceprint',false]]){const el=$(sel,page);el.setAttribute('aria-checked',String(prefs[key]??def));el.setAttribute('aria-label',key==='autoSummary'?'自动生成摘要':'声纹识别');el.addEventListener('click',()=>{try{repo.settings({[key]:el.getAttribute('aria-checked')==='true'});}catch(e){el.setAttribute('aria-checked',String(prefs[key]??def));showToast(e.message);}});}
    const summary=$('[data-settings-summary-copy]',page);if(summary)summary.textContent=prefs.autoSummary===false?'已关闭自动摘要':prefs['summary-template']?'已保存默认摘要偏好':'新录音使用默认摘要偏好';
    $('.settings-float',page).insertAdjacentHTML('beforeend',`<section class="settings-float-section"><div class="settings-float-head"><h4>日程与待办提醒</h4><p>当前原型仅在此页面打开时提供站内演示提醒，不会发送系统或手机通知。</p></div><label class="pa-check"><input id="pa-notifications" type="checkbox" ${prefs.notifications?'checked':''}> 开启站内演示提醒</label></section>`);
    $('#pa-notifications').onchange=e=>{try{repo.settings({notifications:e.target.checked});}catch(err){e.target.checked=!e.target.checked;showToast(err.message);}};
    $('[data-settings-action="logout"]',page).onclick=()=>modal('退出登录？','<p>当前个人记录会保留在此浏览器。</p>','退出登录',()=>location.replace(new URL('../auth-shell.html',location.href).href));
  }
  const oldSettings=window.openUserSettings;window.openUserSettings=()=>{if(guard(()=>window.openUserSettings()))return;hideAgent();oldSettings();setupSettings();};
  function handle(action,id){
    if(action==='todos')return showList('todo');if(action==='new-todo')return newRecord('todo');if(action==='new-schedule')return newRecord('schedule');
    if(action==='back')return showList(listType);if(action==='archive')return openArchive();if(action==='edit'||action==='edit-reminder')return edit();if(action==='toggle')return toggle(id);
    if(action==='filter'){status=id;return renderList();}if(action==='cancel-edit'){if(guard(()=>{editing=false;selected?open(selected):showList(listType);}))return;editing=false;return selected?open(selected):showList(listType);}
    if(action==='modal-confirm')return confirmModal();if(action==='modal-cancel')return cancelModal();
    if(action==='discard'){editing=false;agentDraft=null;const next=continuation;continuation=null;closeModal();return next?.();}
    if(action==='agent'||action==='recall')return showAgent();if(action==='close-agent'){if(guard(()=>{agentDraft=null;hideAgent();}))return;agentDraft=null;return hideAgent();}
    if(action==='agent-example'){$('#pa-prompt').value='明天 14:00–15:00，安排「产品方案讨论」';return $('#pa-prompt').focus();}
    if(action==='source-session')return showAgent(id);if(action==='open-created'){agentDraft=null;return open(id);}
    if(action==='notifications')return window.openUserSettings();
    if(action==='meeting'){const m=meetings().find(x=>x.id===id);if(!m)return showToast('这场会议已不可用');hideAgent();window.MeetingDetail.open(m.title);return;}
    if(action==='notes'){const r=record(selected);modal('我的备注',`<label class="pa-field">只有你可以编辑这条备注<textarea name="notes" rows="7" maxlength="2000" placeholder="添加需要记住的内容">${esc(r.notes)}</textarea><small>最多 2000 字</small></label>`,'保存',()=>{repo.save({...r,notes:$('[name=notes]',dialog).value});sync();renderDetail();},()=>{if($('[name=notes]',dialog).value!==r.notes){const notes=$('[name=notes]',dialog).value;closeModal();modal('保留备注修改？','<p>你有尚未保存的备注。</p>'+button('drop-notes','放弃修改'),'保存',()=>{repo.save({...r,notes});sync();renderDetail();});return false;}});return;}
    if(action==='drop-notes')return closeModal();
    if(action==='links'){const r=record(selected);modal('关联会议与总结',`<p>选择当前个人空间中的会议，可同时关联多场。</p><div class="pa-meeting-choices">${meetings().map(m=>`<label class="pa-meeting-choice"><input type="checkbox" name="linked" value="${esc(m.id)}" ${r.links.includes(m.id)?'checked':''}><span><strong>${esc(m.title)}</strong><small>${esc(m.created)} · ${esc(m.source)}</small><details><summary>展开总结</summary><p>${esc(m.summary)}</p></details></span></label>`).join('')||'<p>暂无可关联会议</p>'}</div>`,'确认关联',()=>{repo.save({...r,links:$$('[name=linked]:checked',dialog).map(el=>el.value)});sync();renderDetail();});return;}
    if(action==='record'){recordingAsset=selected;hideAgent();window.RecordingUI.start();$('#recording-name').textContent=record(selected).title;showToast('已开始演示录音；结束后关联到当前日程');}
  }
  document.addEventListener('click',e=>{const b=e.target.closest('[data-pa]');if(b&&personal()){e.preventDefault();try{handle(b.dataset.pa,b.dataset.id);}catch(err){showToast(err.message);}}const entry=e.target.closest('[data-personal-open]');if(entry&&personal())open(entry.dataset.personalOpen);});
  document.addEventListener('keydown',e=>{if(e.target.matches('[data-personal-open][role=button]')&&['Enter',' '].includes(e.key)){e.preventDefault();e.target.click();}});
  document.addEventListener('input',e=>{if(e.target.id==='pa-search'){search=e.target.value;renderRows();}});
  document.addEventListener('submit',e=>{if(e.target.id==='pa-edit-form'){e.preventDefault();saveDraft();}if(e.target.id==='pa-agent-prompt'){e.preventDefault();generate($('#pa-prompt').value);}if(e.target.id==='pa-agent-form'){e.preventDefault();confirmAgent();}if(e.target.classList.contains('pa-modal-form')){e.preventDefault();confirmModal();}});
  // Guard navigation before other workspaces' handlers run; never move a personal draft to Team.
  window.addEventListener('click',e=>{if(!personal()||e.target.closest('#personal-actions,#pa-agent,.pa-dialog'))return;const target=e.target.closest('[data-ws-action="switch"],[data-ws-action="page"],[data-ws-action="logout"],.sidebar-quick-nav button,[data-meeting-view],[data-profile-action],#home-entry');if(target&&guard(()=>target.click())){e.preventDefault();e.stopImmediatePropagation();}},true);
  document.addEventListener('recording-finished',e=>{if(!recordingAsset||!personal())return;const id=recordingAsset;try{repo.recording(id,record(id).title+' · 会议录音',e.detail.seconds);recordingAsset=null;sync();open(id);}catch(err){showToast(err.message);}});
  $('#recording-abandon').addEventListener('click',()=>{recordingAsset=null;});
  window.addEventListener('beforeunload',e=>{const form=$('#pa-edit-form');if((editing&&form&&JSON.stringify(values(form,draft))!==draftBaseline)||agentDraft){e.preventDefault();e.returnValue='';}});
  new MutationObserver(()=>{if(!personal()||root.hidden&&$('[data-main-view="home"]').hidden){hideAgent();$$('audio',root).forEach(a=>a.pause());}if(!personal())recordingAsset=null;}).observe(document.body,{attributes:true,subtree:true,attributeFilter:['data-ws-type','hidden']});
  window.addEventListener('storage',e=>{if(e.key!==M.KEY)return;try{repo.reload();sync();if(!editing&&!root.hidden){selected?renderDetail():renderList();}else if(editing)showToast('另一页面已更新；请先保留输入，再重新打开记录');}catch(err){showToast(err.message);}});
  const reminded=new Set();setInterval(()=>{if(!personal()||!repo.snapshot().settings.notifications)return;for(const r of repo.snapshot().records){if(r.done||r.reminder==='none')continue;const at=Date.parse(r.start+':00+08:00')-Number(r.reminder)*60000,key=r.id+':'+at;if(Date.now()>=at&&Date.now()-at<60000&&!reminded.has(key)){reminded.add(key);showToast('提醒：'+r.title);}}},15000);
  window.PersonalAssets={open,toggle,guard,snapshot:()=>repo.snapshot()};sync();
})();
